#!/usr/bin/env node
/**
 * Tests for owner answers to an implementer `stop` question in the runs that have no second call of their own (a
 * continuation and the preview pass): an answer from a resolution or accepted by the judge is applied by one implementer
 * "(answers)" call, never left as a note. Harness: tools/dev-loop.harness.mjs.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS_M, impl } from './dev-loop.harness.mjs';

const stopQuestion = { text: 'Who owns the data?', default: 'the tenant', why: 'unsaid', reversible: false, axis: 'data' };
const ANSWER = 'the tenant owns it, nobody else';
const REQUEST = 'Fix the lookup. The tenant owns the data, nobody else.';
const answerCalls = (calls) => calls.filter((c) => c.opts.agentType === 'implementer' && /\(answers\)$/.test(c.opts.label ?? ''));

test('given a resumed continuation whose stop question the owner answered, when the loop runs, then one implementer (answers) call applies the answer', async () => {
  // Given
  const resolutions = [{ round: 0, answers: [{ text: stopQuestion.text, answer: ANSWER }] }];
  const impls = [impl({ remaining: ['finish the query'] }), impl({ questions: [stopQuestion] }), impl()];

  // When
  const { out, calls } = await run({ ...ARGS_M, resolutions }, [], impls);

  // Then
  const applied = answerCalls(calls);
  assert.equal(applied.length, 1);
  assert.match(applied[0].prompt, new RegExp(`${stopQuestion.text.replace('?', '\\?')} -> ${ANSWER}`));
  assert.notEqual(out.stall?.why, 'question');
});

test('given a continuation stop question the judge accepts an answer for, when the loop runs, then the same (answers) call runs with the owner sentence', async () => {
  // Given
  const impls = [impl({ remaining: ['finish the query'] }), impl({ questions: [stopQuestion] }), impl()];
  const judge = () => ({ judgments: [{ text: stopQuestion.text, status: 'answered', answer: 'the tenant', quote: 'The tenant owns the data' }] });

  // When
  const { out, calls } = await run({ ...ARGS_M, request: REQUEST }, [], impls, { judge });

  // Then
  const applied = answerCalls(calls);
  assert.equal(applied.length, 1);
  assert.match(applied[0].prompt, /The tenant owns the data, nobody else\./);
  assert.equal(out.judged.length, 1);
});

test('given a preview feedback pass whose stop question the owner answered, when the loop runs, then one implementer (answers) call applies the answer', async () => {
  // Given
  const preview = 'the order list page /orders';
  const first = await run({ ...ARGS_M, preview }, [], [impl()]);
  const previewText = first.out.stall.questions[0].text;
  const resolutions = [{ round: 0, answers: [{ text: previewText, answer: 'show the totals column too' }, { text: stopQuestion.text, answer: ANSWER }] }];
  const impls = [impl(), impl({ questions: [stopQuestion] }), impl()];

  // When
  const { calls } = await run({ ...ARGS_M, preview, resolutions }, [], impls);

  // Then
  const applied = answerCalls(calls);
  assert.equal(applied.length, 1);
  assert.equal(applied[0].opts.label, 'implement the change (preview feedback) (answers)');
  assert.match(applied[0].prompt, new RegExp(ANSWER));
});

test('given a preview feedback pass whose stop question the judge accepts an answer for, when the loop runs, then the (answers) call runs, no silent OK', async () => {
  // Given
  const preview = 'the order list page /orders';
  const first = await run({ ...ARGS_M, preview, request: REQUEST }, [], [impl()]);
  const previewText = first.out.stall.questions[0].text;
  const resolutions = [{ round: 0, answers: [{ text: previewText, answer: 'show the totals column too' }] }];
  const impls = [impl(), impl({ questions: [stopQuestion] }), impl()];
  const judge = () => ({ judgments: [{ text: stopQuestion.text, status: 'answered', answer: 'the tenant', quote: 'The tenant owns the data' }] });

  // When
  const { calls } = await run({ ...ARGS_M, preview, request: REQUEST, resolutions }, [], impls, { judge });

  // Then
  assert.equal(answerCalls(calls).length, 1);
});

test('given a continuation whose (answers) call returns nothing, when the loop runs, then it stalls and the answer is not dropped', async () => {
  // Given
  const resolutions = [{ round: 0, answers: [{ text: stopQuestion.text, answer: ANSWER }] }];
  const impls = [impl({ remaining: ['finish the query'] }), impl({ questions: [stopQuestion] }), null];

  // When
  const { out, calls } = await run({ ...ARGS_M, resolutions }, [], impls);

  // Then
  assert.equal(answerCalls(calls).length, 1);
  assert.match(out.stall?.reason ?? '', /owner's answers/);
});
